 1 0 1 0-2 0v6a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V5a1 1 0 0 1 1-1h6a1 1 0 1 0 0-2H5Z"/></svg>'; private const CHEVRON = '<svg class="dzp-chevron" viewBox="0 0 24 24" aria-hidden="true"><path fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" d="m6 9 6 6 6-6"/></svg>'; public static function gallery(?DiscordBot $bot, ?array $design = null, ?array $commands = null): array { $bot = $bot === null ? new DiscordBot(['user_id' => null, 'name' => BotConfig::panelName(), 'application_id' => '0']) : clone $bot; $settings = (array) ($bot->settings ?? []); if ($design !== null) { $settings['design'] = BotSettings::normaliseDesign($design); } if ($commands !== null) { $settings['commands'] = BotSettings::normaliseCommands($commands, !$bot->isGlobal()); } $bot->settings = $settings; $active = BotSettings::active($bot); $commandPublic = BotSettings::visibility($bot) === 'public'; $previous = [Style::current()]; Style::use(Style::for($bot), $active, BotSettings::powerActions($bot)); $servers = Samples::servers(); $live = Samples::live(); $server = $servers[0]; $user = new User(['username' => 'anthony', 'email' => 'anthony@example.com', 'name_first' => 'Anthony', 'name_last' => 'Builder']); $cards = []; $add = function (string $key, string $title, string $command, callable $build, ?bool $public = null) use (&$cards, $active, $bot, $commandPublic) { if ($command !== '' && !in_array($command, $active, true)) { return; } $public ??= $commandPublic; try { $cards[] = [ 'key' => $key, 'title' => $title, 'command' => $command, 'html' => self::render($build(), $bot, $public, $command), ]; } catch (Throwable $exception) { $cards[] = ['key' => $key, 'title' => $title, 'command' => $command, 'html' => '<div class="dzp-error">' . e($exception->getMessage()) . '</div>']; } }; $add('help', '/help', 'help', fn () => Cards::help('anthony', true, !$bot->isGlobal())); $add('servers', '/servers', 'servers', fn () => ServerList::compose(array_map(null, $servers, $live), 1, 2, 7, 'anthony')); $add('controlpanel', '/controlpanel', 'controlpanel', fn () => ControlPanel::compose($server, $live[0], array_slice(Samples::console(), -Style::current()->consoleLines()), null, null, false, true)); $add('backups', '/backups', 'backups', fn () => Backups::composeList($server, Samples::backups(), 3, 'Started **Weekly**. Press refresh in a moment to see it finish.')); $add('connect', '/connect', 'connect', fn () => ServerInfo::composeConnect($server, Samples::subdomains(), 'anthony')); $add('activity', '/activity', 'activity', fn () => ServerInfo::composeActivity($server, Samples::activity())); $add('billing', '/billing', 'billing', fn () => ServerInfo::composeBilling($server, Samples::billing())); $add('account', '/account', 'account', fn () => Cards::account($user, 7, BotConfig::panelLogo(), $bot->isGlobal() ? 'anthony' : null, CarbonImmutable::now()->subDays(40)->toAtomString(), !$bot->isGlobal())); $alert = new DiscordBotAlert([ 'role_id' => Samples::ROLE, 'channel_id' => Samples::CHANNEL, 'memory' => 85, 'cpu' => 90, 'offline' => true, 'cooldown' => 15, ]); $add('alert-hot', 'Alert · running hot', 'alerts', fn () => Alerts::hot($alert, $server, ['memory'], [ 'state' => 'running', 'usage' => ['memory' => (int) (3.7 * 1073741824), 'cpu' => 121, 'disk' => (int) (6.2 * 1073741824), 'rx' => 0, 'tx' => 0, 'uptime' => 0], ], ['memory' => 92.5, 'cpu' => 60.5, 'disk' => 31], true), true); $add('alert-crash', 'Alert · went offline', 'alerts', fn () => Alerts::crashed($alert, $server), true); $add('alerts-list', '/alerts list', 'alerts', fn () => Alerts::list(new Collection())); Style::use($previous[0], null); return $cards; } public static function render(array $message, DiscordBot $bot, bool $public = false, string $command = ''): string { $body = ''; foreach ((array) ($message['components'] ?? []) as $component) { $body .= self::component($component); } $avatar = e($bot->application_id !== '0' ? $bot->avatarUrl() : (BotConfig::panelLogo() ?? 'https://cdn.discordapp.com/embed/avatars/0.png')); $name = e($bot->name ?: BotConfig::panelName()); $reply = $command !== '' && !$public; $invoker = $reply ? '<div class="dzp-spine"></div><div class="dzp-reply"><img src="https://cdn.discordapp.com/embed/avatars/1.png" alt=""><span class="dzp-reply-name">anthony</span><span>used</span><span class="dzp-reply-cmd">/' . e($command) . '</span></div>' : ''; $footer = $public ? '' : '<div class="dzp-ephemeral">' . self::EYE . '<span>Only you can see this</span><span aria-hidden="true">•</span><a>Dismiss message</a></div>'; return '<div class="dzp-msg' . ($reply ? ' dzp-has-reply' : '') . ($public ? '' : ' dzp-eph') . '">' . $invoker . '<img class="dzp-avatar" src="' . $avatar . '" alt="">' . '<div class="dzp-head"><span class="dzp-name">' . $name . '</span><span class="dzp-app">APP</span><span class="dzp-time">' . e(CarbonImmutable::now()->format("g:i\u{202F}A")) . '</span></div>' . '<div class="dzp-body">' . $body . '</div>' . $footer . '</div>'; } private static function component(array $component): string { $children = fn (string $key) => implode('', array_map(fn (array $child) => self::component($child), (array) ($component[$key] ?? []))); return match ((int) ($component['type'] ?? 0)) { 17 => isset($component['accent_color']) ? '<div class="dzp-container dzp-accent" style="--dzp-accent:' . sprintf('#%06x', (int) $component['accent_color']) . '">' . $children('components') . '</div>' : '<div class="dzp-container">' . $children('components') . '</div>', 10 => '<div class="dzp-text">' . self::markdown((string) ($component['content'] ?? '')) . '</div>', 9 => '<div class="dzp-section"><div class="dzp-section-body">' . $children('components') . '</div>' . '<div class="dzp-accessory">' . self::component((array) ($component['accessory'] ?? [])) . '</div></div>', 11 => '<img class="dzp-thumb" src="' . e((string) ($component['media']['url'] ?? '')) . '" alt="">', 12 => self::mediaGallery((array) ($component['items'] ?? [])), 14 => '<div class="dzp-sep' . (($component['divider'] ?? true) ? ' dzp-sep-line' : '') . ((int) ($component['spacing'] ?? 1) === 2 ? ' dzp-sep-lg' : '') . '"></div>', 1 => '<div class="dzp-row">' . $children('components') . '</div>', 2 => self::button($component), 3, 5, 6, 7, 8 => self::select($component), default => '', }; } private static function mediaGallery(array $items): string { $images = array_map(fn (array $item) => '<img src="' . e((string) ($item['media']['url'] ?? '')) . '" alt="">', array_slice($items, 0, 10)); return '<div class="dzp-gallery dzp-gallery-' . min(count($images), 4) . '">' . implode('', $images) . '</div>'; } private static function button(array $button): string { $style = self::BUTTONS[(int) ($button['style'] ?? 2)] ?? 'secondary'; $emoji = isset($button['emoji']) ? self::componentEmoji((array) $button['emoji']) : ''; $label = isset($button['label']) ? '<span class="dzp-btn-label">' . self::plain((string) $button['label']) . '</span>' : ''; $launch = $style === 'link' ? self::LAUNCH : ''; return '<span class="dzp-btn dzp-btn-' . $style . (($button['disabled'] ?? false) ? ' dzp-disabled' : '') . '">' . $emoji . $label . $launch . '</span>'; } private static function select(array $select): string { $chosen = array_values(array_filter((array) ($select['options'] ?? []), fn ($option) => is_array($option) && ($option['default'] ?? false))); $value = $chosen === [] ? '<span class="dzp-select-placeholder">' . self::plain((string) ($select['placeholder'] ?? 'Make a selection')) . '</span>' : '<span class="dzp-select-value">' . implode(', ', array_map( fn (array $option) => (isset($option['emoji']) ? self::componentEmoji((array) $option['emoji']) : '') . self::plain((string) ($option['label'] ?? '')), $chosen, )) . '</span>'; return '<div class="dzp-select' . (($select['disabled'] ?? false) ? ' dzp-disabled' : '') . '">' . $value . self::CHEVRON . '</div>'; } public static function markdown(string $text): string { $out = ''; $lines = explode("\n", rtrim(str_replace("\r\n", "\n", $text), "\n")); $count = count($lines); $paragraph = []; $flush = function () use (&$paragraph, &$out) { if ($paragraph === []) { return; } $html = implode('<br>', array_map(fn (string $line) => self::inline($line), $paragraph)); $out .= '<div class="dzp-p">' . $html . (end($paragraph) === '' ? '<br>' : '') . '</div>'; $paragraph = []; }; for ($index = 0; $index < $count; ++$index) { $line = $lines[$index]; if (str_starts_with($line, '```')) { $flush(); $code = []; $rest = substr($line, 3); if (str_contains($rest, '```')) { $out .= '<pre class="dzp-pre"><code>' . self::ansi(substr($rest, 0, strpos($rest, '```'))) . '</code></pre>'; continue; } for (++$index; $index < $count && !str_starts_with($lines[$index], '```'); ++$index) { $code[] = $lines[$index]; } $out .= '<pre class="dzp-pre"><code>' . implode("\n", array_map(fn (string $row) => self::ansi($row), $code)) . '</code></pre>'; continue; } if (preg_match('/^(#{1,3}) +(\S.*)$/', $line, $match) === 1) { $flush(); $level = strlen($match[1]); $out .= "<h{$level} class=\"dzp-h{$level}\">" . self::inline($match[2]) . "</h{$level}>"; } elseif (preg_match('/^-# +(\S.*)$/', $line, $match) === 1) { $flush(); $out .= '<div class="dzp-subtext">' . self::inline($match[1]) . '</div>'; } elseif (str_starts_with($line, '>>> ')) { $flush(); $out .= '<blockquote class="dzp-quote"><div>' . implode('<br>', array_map(fn (string $row) => self::inline($row), [substr($line, 4), ...array_slice($lines, $index + 1)])) . '</div></blockquote>'; $index = $count; } elseif (str_starts_with($line, '> ') || $line === '>') { $flush(); $quoted = []; for (; $index < $count && (str_starts_with($lines[$index], '> ') || $lines[$index] === '>'); ++$index) { $quoted[] = self::inline((string) substr($lines[$index], 2)); } --$index; $out .= '<blockquote class="dzp-quote"><div>' . implode('<br>', $quoted) . '</div></blockquote>'; } elseif (preg_match('/^ {0,2}([-*]|\d{1,3}\.) +\S/', $line, $match) === 1) { $flush(); $ordered = !in_array($match[1], ['-', '*'], true); $items = []; for (; $index < $count && preg_match('/^ {0,2}([-*]|\d{1,3}\.) +(\S.*)$/', $lines[$index], $item) === 1 && in_array($item[1], ['-', '*'], true) !== $ordered; ++$index) { $items[] = '<li>' . self::inline($item[2]) . '</li>'; } --$index; $out .= $ordered ? '<ol class="dzp-list" start="' . (int) $match[1] . '">' . implode('', $items) . '</ol>' : '<ul class="dzp-list">' . implode('', $items) . '</ul>'; } else { $paragraph[] = $line; } } $flush(); return $out; } private static function inline(string $text): string { $pattern = '/(\\\\[\\\\*_`~|>\[\]#\-+.:<])|(``(?:[^`]|`(?!`))+``|`[^`]+`)|(<(a?):(\w{2,32}):(\d{17,20})>)|(<t:(-?\d{1,13})(?::([tTdDfFR]))?>)|(<@&(\d+)>)|(<#(\d+)>)|(<@!?(\d+)>)|(<\/([\w -]{1,96}):\d+>)' . '|(\[([^\]\n]+)\]\(<?(https?:\/\/[^\s)>]+)>?\))|(<?(https?:\/\/[^\s<]+[^<.,:;"\'\)\]\s>]))>?|(\*\*(?=\S)(.+?)\*\*)|(__(?=\S)(.+?)__)|(\*(?=[^\s*])(.+?)\*(?!\*))|((?<![A-Za-z0-9_])_(?=\S)(.+?)_(?![A-Za-z0-9_]))|(~~(?=\S)(.+?)~~)|(\|\|(.+?)\|\|)/u'; $out = ''; $offset = 0; while (preg_match($pattern, $text, $match, PREG_OFFSET_CAPTURE, $offset) === 1) { [$token, $position] = $match[0]; $out .= self::plain(substr($text, $offset, $position - $offset)); $group = fn (int $index) => isset($match[$index]) && $match[$index][1] !== -1 ? $match[$index][0] : null; $out .= match (true) { $group(1) !== null => e(substr($token, 1)), $group(2) !== null => '<code class="dzp-code">' . e(str_starts_with($token, '``') ? trim(substr($token, 2, -2)) : substr($token, 1, -1)) . '</code>', $group(3) !== null => '<img class="dzp-emoji" src="https://cdn.discordapp.com/emojis/' . $group(6) . '.' . ($group(4) === 'a' ? 'gif' : 'webp') . '?size=48" alt=":' . e($group(5)) . ':">', $group(7) !== null => '<span class="dzp-ts">' . e(self::time((int) $group(8), $group(9) ?? 'f')) . '</span>', $group(10) !== null => '<span class="dzp-mention">@' . ($group(11) === Samples::ROLE ? 'On-call' : 'role') . '</span>', $group(12) !== null => '<span class="dzp-mention">#' . ($group(13) === Samples::CHANNEL ? 'server-alerts' : 'channel') . '</span>', $group(14) !== null => '<span class="dzp-mention">@anthony</span>', $group(16) !== null => '<span class="dzp-mention">/' . e($group(17)) . '</span>', $group(18) !== null => '<a class="dzp-link">' . self::inline($group(19)) . '</a>', $group(21) !== null => '<a class="dzp-link">' . e($group(22)) . '</a>', $group(23) !== null => '<strong>' . self::inline($group(24)) . '</strong>', $group(25) !== null => '<u>' . self::inline($group(26)) . '</u>', $group(27) !== null => '<em>' . self::inline($group(28)) . '</em>', $group(29) !== null => '<em>' . self::inline($group(30)) . '</em>', $group(31) !== null => '<s>' . self::inline($group(32)) . '</s>', $group(33) !== null => '<span class="dzp-spoiler">' . self::inline($group(34)) . '</span>', default => self::plain($token), }; $offset = $position + strlen($token); } return $out . self::plain(substr($text, $offset)); } private static function plain(string $text): string { return (string) preg_replace_callback(self::EMOJI, fn (array $match) => self::twemoji($match[0]), e($text)); } private static function componentEmoji(array $emoji): string { if (!empty($emoji['id'])) { return '<img class="dzp-emoji" src="https://cdn.discordapp.com/emojis/' . e((string) $emoji['id']) . '.' . (($emoji['animated'] ?? false) ? 'gif' : 'webp') . '?size=48" alt="">'; } $name = (string) ($emoji['name'] ?? ''); return preg_match(self::EMOJI, $name) === 1 ? self::twemoji($name) : e($name); } private static function twemoji(string $emoji): string { $sequence = str_contains($emoji, "\u{200D}") ? $emoji : str_replace("\u{FE0F}", '', $emoji); $code = implode('-', array_map(fn (string $char) => dechex(mb_ord($char)), mb_str_split($sequence))); return '<img class="dzp-emoji" src="' . self::TWEMOJI . $code . '.svg" alt="' . e($emoji) . '" draggable="false">'; } private static function time(int $timestamp, string $style): string { $time = CarbonImmutable::createFromTimestamp($timestamp, config('app.timezone')); return match ($style) { 'R' => self::relative($time), 't' => $time->format('g:i A'), 'T' => $time->format('g:i:s A'), 'd' => $time->format('m/d/Y'), 'D' => $time->format('F j, Y'), 'F' => $time->format('l, F j, Y g:i A'), default => $time->format('F j, Y g:i A'), }; } private static function relative(CarbonImmutable $time): string { $seconds = abs(CarbonImmutable::now()->getTimestamp() - $time->getTimestamp()); $minutes = $seconds / 60; $hours = $minutes / 60; $days = $hours / 24; $span = match (true) { $seconds < 45 => 'a few seconds', $seconds < 90 => 'a minute', $minutes < 45 => round($minutes) . ' minutes', $minutes < 90 => 'an hour', $hours < 22 => round($hours) . ' hours', $hours < 36 => 'a day', $days < 26 => round($days) . ' days', $days < 45 => 'a month', $days < 320 => max(2, (int) round($days / 30.4)) . ' months', $days < 548 => 'a year', default => round($days / 365) . ' years', }; return $time->isFuture() ? "in {$span}" : "{$span} ago"; } private static function ansi(string $line): string { $out = ''; $open = false; $parts = preg_split('/\e\[([0-9;]*)m/', $line, -1, PREG_SPLIT_DELIM_CAPTURE) ?: [$line]; foreach ($parts as $index => $part) { if ($index % 2 === 0) { $out .= e($part); continue; } if ($open) { $out .= '</span>'; $open = false; } $styles = []; foreach (array_map('intval', explode(';', $part === '' ? '0' : $part)) as $code) { if (isset(self::ANSI[$code])) { $styles[] = 'color:' . self::ANSI[$code]; } elseif (isset(self::ANSI_BACKGROUND[$code])) { $styles[] = 'background-color:' . self::ANSI_BACKGROUND[$code]; } elseif ($code === 1) { $styles[] = 'font-weight:700'; } elseif ($code === 4) { $styles[] = 'text-decoration:underline'; } } if ($styles !== []) { $out .= '<span style="' . implode(';', $styles) . '">'; $open = true; } } return $out . ($open ? '</span>' : ''); } private static function fonts(): string { $css = ''; $ranges = [ 'latin' => 'U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD', 'latin-ext' => 'U+0100-02BA,U+02BD-02C5,U+02C7-02CC,U+02CE-02D7,U+02DD-02FF,U+0304,U+0308,U+0329,U+1D00-1DBF,U+1E00-1E9F,U+1EF2-1EFF,U+2020,U+20A0-20AB,U+20AD-20C0,U+2113,U+2C60-2C7F,U+A720-A7FF', ]; foreach (['dzp-sans' => ['source-sans-3', [400, 500, 600, 700, 800]], 'dzp-mono' => ['source-code-pro', [400, 600]]] as $family => [$slug, $weights]) { foreach ($weights as $weight) { foreach ($ranges as $subset => $range) { $css .= "@font-face{font-family:\"{$family}\";font-style:normal;font-weight:{$weight};font-display:swap;" . "src:url(https://fonts.bunny.net/{$slug}/files/{$slug}-{$subset}-{$weight}-normal.woff2) format(\"woff2\");unicode-range:{$range}}\n"; } } } return $css; } public static function css(): string { return self::fonts() . <<<'CSS'
.dzp-msg{position:relative;min-height:76px;padding:16px 16px 16px 72px;background:#1a1a1e;color:#efeff0;font-family:"gg sans","dzp-sans","Noto Sans","Helvetica Neue",Helvetica,Arial,sans-serif;font-size:16px;font-weight:400;line-height:22px;letter-spacing:normal;font-feature-settings:normal;font-variation-settings:normal;text-align:left;word-break:normal;overflow-wrap:break-word;-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale}
.dzp-msg *{box-sizing:border-box}
.dzp-msg.dzp-eph{border-left:3px solid #5865f2;background:linear-gradient(rgba(88,101,242,.08),rgba(88,101,242,.08)) #1a1a1e;backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px)}
.dzp-msg.dzp-has-reply{min-height:98px}
.dzp-spine{position:absolute;left:35px;top:24px;width:33px;height:14px;border-left:2px solid #4c4c53;border-top:2px solid #4c4c53;border-top-left-radius:6px}
.dzp-reply{display:flex;align-items:center;gap:4px;height:18px;margin-bottom:4px;font-size:14px;line-height:18px;color:#94959c;white-space:nowrap;overflow:hidden}
.dzp-reply img{width:16px;height:16px;border-radius:50%;flex-shrink:0}
.dzp-reply-name{color:#efeff0;font-weight:500}
.dzp-reply-cmd{color:#4c97f0}
.dzp-avatar{position:absolute;left:16px;top:18px;width:40px;height:40px;border-radius:50%;object-fit:cover;background:#242429}
.dzp-has-reply .dzp-avatar{top:40px}
.dzp-head{display:flex;align-items:center;min-height:22px;white-space:nowrap}
.dzp-name{color:#fbfbfb;font-weight:500;overflow:hidden;text-overflow:ellipsis}
.dzp-app{display:inline-flex;align-items:center;flex-shrink:0;height:15px;margin:0 4px;padding:0 5px;border-radius:4px;background:#5865f2;color:#fff;font-size:12px;font-weight:700;line-height:15px}
.dzp-time{margin-left:4px;color:#82838b;font-size:13px}
.dzp-body{display:flex;flex-direction:column;gap:8px;width:fit-content;max-width:100%;padding:2px 0}
.dzp-container{position:relative;display:flex;flex-direction:column;gap:8px;min-width:0;padding:16px;border:1px solid rgba(151,151,159,.2);border-radius:8px;background:#242429;overflow:hidden}
.dzp-accent::before{content:"";position:absolute;left:0;top:0;bottom:0;width:4px;background:var(--dzp-accent)}
.dzp-container .dzp-text{font-size:14px}
.dzp-text{min-width:0}
.dzp-text>:first-child{margin-top:0}
.dzp-text>:last-child{margin-bottom:0}
.dzp-h1,.dzp-h2,.dzp-h3{margin:16px 0 8px;padding:0;color:#fbfbfb;font-family:inherit;letter-spacing:normal;font-weight:800;line-height:1.375em}
.dzp-h1{font-size:24px}
.dzp-h2{font-size:20px}
.dzp-h3{font-size:16px}
.dzp-subtext{color:#94959c;font-size:13px;line-height:18px}
.dzp-text strong{font-weight:700}
.dzp-text em{font-style:italic}
.dzp-list{margin:4px 0 0 16px;padding:0;list-style-position:outside}
ul.dzp-list{list-style:disc}
ol.dzp-list{list-style:decimal}
.dzp-list li{margin-bottom:4px}
.dzp-list li:last-child{margin-bottom:0}
.dzp-quote{display:flex;max-width:90%;margin:0;padding:0;border:0;font-size:inherit}
.dzp-quote::before{content:"";flex-shrink:0;width:4px;border-radius:4px;background:#4c4c53}
.dzp-quote>div{min-width:0;padding:0 8px 0 12px}
.dzp-code,.dzp-pre{font-family:"gg mono","dzp-mono","Source Code Pro",Consolas,"Andale Mono WT","Andale Mono","Lucida Console","Lucida Sans Typewriter","DejaVu Sans Mono","Bitstream Vera Sans Mono","Liberation Mono","Nimbus Mono L",Monaco,"Courier New",Courier,monospace}
.dzp-code{margin:-.2em 0;padding:0 .2em;border:1px solid rgba(142,146,186,.25);border-radius:4px;background:rgba(88,101,242,.08);color:inherit;font-size:85%;line-height:1.125rem;white-space:pre-wrap}
.dzp-pre{margin:6px 0 0;padding:0;border:0;border-radius:0;background:none;color:inherit;font-size:inherit;line-height:inherit;white-space:pre-wrap;word-break:normal;overflow:visible}
.dzp-pre code{display:block;padding:7px;border:1px solid rgba(142,146,186,.25);border-radius:4px;background:rgba(88,101,242,.08);color:#c5c6cb;font-family:inherit;font-size:14px;line-height:18px;white-space:pre-wrap;overflow-wrap:anywhere}
.dzp-emoji{display:inline-block;width:1.375em;height:1.375em;max-width:none;margin:0 .05em 0 .1em;object-fit:contain;vertical-align:bottom}
.dzp-mention{padding:0 2px;border-radius:3px;background:rgba(88,101,242,.3);color:#dee0fc;font-weight:600}
.dzp-ts{padding:0 2px;border-radius:3px;background:rgba(151,151,159,.12)}
.dzp-link{color:#4c97f0;text-decoration:none;cursor:pointer}
.dzp-link:hover{text-decoration:underline}
.dzp-spoiler{border-radius:4px;background:#666771;color:transparent}
.dzp-spoiler img{visibility:hidden}
.dzp-section{display:flex;align-items:flex-start;gap:16px}
.dzp-section-body{display:flex;flex:1;flex-direction:column;gap:4px;min-width:0}
.dzp-accessory{display:flex;flex-shrink:0}
.dzp-thumb{display:block;width:85px;height:85px;border-radius:8px;object-fit:cover;background:rgba(151,151,159,.12)}
.dzp-gallery{display:grid;gap:4px;max-width:100%;border-radius:8px;overflow:hidden}
.dzp-gallery img{display:block;width:100%;height:100%;object-fit:cover}
.dzp-gallery-1{justify-items:start}
.dzp-gallery-1 img{width:auto;max-width:100%;height:auto;max-height:350px;border-radius:8px}
.dzp-gallery-2{grid-template-columns:1fr 1fr;aspect-ratio:2/1}
.dzp-gallery-3{grid-template-columns:2fr 1fr;grid-template-rows:1fr 1fr;aspect-ratio:3/2}
.dzp-gallery-3 img:first-child{grid-row:span 2}
.dzp-gallery-4{grid-template-columns:1fr 1fr;aspect-ratio:1}
.dzp-sep{flex-shrink:0;height:1px}
.dzp-sep-line{background:rgba(151,151,159,.2)}
.dzp-sep-lg{margin:8px 0}
.dzp-row{display:flex;flex-wrap:wrap;gap:8px}
.dzp-btn{display:inline-flex;align-items:center;justify-content:center;gap:4px;min-width:60px;height:32px;padding:0 16px;border:1px solid rgba(255,255,255,.08);border-radius:8px;color:#fff;font-size:14px;font-weight:600;line-height:16px;white-space:nowrap;cursor:pointer;user-select:none}
.dzp-btn .dzp-emoji{width:18px;height:18px;margin:0}
.dzp-btn-primary{background:#5865f2}
.dzp-btn-secondary,.dzp-btn-link{border-color:rgba(255,255,255,.02);background:rgba(151,151,159,.12);color:#ebebed}
.dzp-btn-success{background:#00863a}
.dzp-btn-danger{background:#d22d39}
.dzp-launch{width:16px;height:16px;margin-left:4px;flex-shrink:0}
.dzp-disabled{opacity:.5;cursor:not-allowed}
.dzp-select{display:flex;align-items:center;justify-content:space-between;gap:8px;width:100%;max-width:400px;height:44px;padding:0 8px;border:1px solid rgba(151,151,159,.2);border-radius:8px;background:#18181c;font-size:16px;line-height:20px;cursor:pointer}
.dzp-select-placeholder,.dzp-select-value{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.dzp-select-placeholder{color:#aaaab1}
.dzp-select-value{color:#efeff0}
.dzp-select-value .dzp-emoji{margin:0 6px 0 0}
.dzp-chevron{width:20px;height:20px;flex-shrink:0;color:#efeff0}
.dzp-ephemeral{display:flex;align-items:center;gap:4px;margin-top:4px;color:#94959c;font-size:12px;line-height:16px}
.dzp-ephemeral svg{width:16px;height:16px;flex-shrink:0}
.dzp-ephemeral a{color:#4c97f0;text-decoration:none;cursor:pointer}
.dzp-error{color:#f23f43;font-size:13px}
.dzp-msg.dzp-empty{min-height:0;padding:24px;color:#94959c;font-size:14px}
